fn solve(x: i8) -> u8 {
    // Normalize the input angle into [0, 360)
    let angle = {
        let a = x as i32 % 360;
        if a < 0 { a + 360 } else { a }
    };

    let mut best_r: u8 = 0;
    let mut best_dev: i32 = 360; // larger than any possible deviation

    for r in 0..4 {
        // Compute A = (-angle + 90 * r) mod 360, normalized into [0, 360)
        let rotated = {
            let a = -angle + (r * 90);
            let m = a % 360;
            if m < 0 { m + 360 } else { m }
        };

        // Deviation is the shorter distance to vertical (0°)
        let dev = std::cmp::min(rotated, 360 - rotated);

        // Update best rotation if we found a smaller deviation,
        // or same deviation but smaller r
        if dev < best_dev || (dev == best_dev && (r as u8) < best_r) {
            best_dev = dev;
            best_r = r as u8;
        }
    }

    best_r
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_simple() {
        // If x = 0, best is r = 1 (rotate +90 to make it vertical)
        assert_eq!(solve(0), 1);
        // If x = 90, it's already vertical, so r = 0
        assert_eq!(solve(90), 0);
        // If x = 180, 180 away from vertical; any r gives 90 or 270, best is r=2 giving 0
        assert_eq!(solve(180), 2);
        // If x = -90 (i.e., 270), best is r = 2 to get 90 degrees -> vertical
        assert_eq!(solve(-90), 2);
    }

    #[test]
    fn test_ties() {
        // x = 45: rotations give deviations [45, 45, 135, 135], pick smallest r = 0
        assert_eq!(solve(45), 0);
        // x = 315 (-45): deviations [45, 135, 135, 45], tie for r=0 and r=3, pick 0
        assert_eq!(solve(-45), 0);
        // x = 135: deviations [135, 45, 45, 135], tie for r=1 and r=2, pick 1
        assert_eq!(solve(135), 1);
    }
}